    def headnum(i):
        """编号标题行: 行首至多三空格、数字组(可含小节点号)、可选尾点、空白、题文, 且行末为字母(目录行以页码数字结尾)。"""
        out = []
        for l in LST[i]:
            n = 0
            while n < len(l) and l[n] == u' ' and n < 4:
                n += 1
            if n > 3 or not l:
                continue
            if not (u'a' <= l[-1].lower() <= u'z'):
                continue
            j = n
            seg = u''
            while True:
                d = u''
                while j < len(l) and l[j] in DIG:
                    d += l[j]
                    j += 1
                if not d:
                    break
                if j < len(l) and l[j] == u'.':
                    if seg and l[j - 1] == u'.':
                        break
                    seg += (u'.' if seg else u'') + d + u'.'
                    j += 1
                    continue
