    def m_inter(a, b):
        i = j = n = 0
        while i < len(a) and j < len(b):
            if a[i] == b[j]:
                n += 1
                i += 1
                j += 1
            elif a[i] < b[j]:
                i += 1
            else:
                j += 1
        return n


    def m_union(*sets):
        seen = {}
        for s in sets:
            for x in s:
                seen[x] = 1
        return len(seen)


