    assert F[u'cite_2132'] == [0, 1, 0, 4] and F[u'cite_3315'] == [0, 100, 19, 21]
    assert F[u'cite_3315_ns'] == [0, 0, 4, 11] and F[u'cite_3315_sp'] == [0, 100, 15, 10]
    assert F[u'cite_4941'] == [0, 0, 0, 12] and F[u'cite_6221'] == [0, 0, 0, 5]
    assert F[u'cite_7083'] == [0, 0, 6, 13] and F[u'cite_7542'] == [0, 0, 0, 0]
    assert F[u'cite_8415'] == [0, 0, 0, 153] and F[u'cite_ns_3315'] == [0, 100, 19, 21]
    assert F[u'y_cite_ledger_3315'] == [0, 0, 0, 0] and F[u'y_cite_ledger_3315_sum'] == 0
    assert F[u'cat_bcp'] == [0, 0, 0, 0] and F[u'cat_exp'] == [0, 0, 0, 0] and F[u'cat_info'] == [0, 0, 0, 0]
    assert F[u'cat_std'] == [1, 1, 1, 1] and F[u'obs_hdr'] == [1, 0, 0, 1]
    assert F[u'obsoleted_by'] == [0, 0, 0, 3] and F[u'upd_hdr'] == [0, 0, 1, 0]
    assert F[u'issn_hdr'] == [0, 0, 1, 1] and F[u'req_rc'] == [1, 1, 1, 1]
    assert F[u'sec_a'] == [1223, 846, 101, 1462] and F[u'sec_b'] == [1386, 878, 130, 1544]
    assert F[u'sec_head'] == ['4.1 Constructing and sending DHCP messages', '5.5. Transmission and Retransmission Parameters', '3.  Updates to SOL_MAX_RT and INF_MAX_RT in RFC 3315', '7.6.  Transmission and Retransmission Parameters']
    assert F[u'sec_hit'] == [1, 1, 1, 1] and F[u'sec_len'] == [8944, 1583, 970, 5162]
    assert F[u'sec_len_a'] == 8944 and F[u'sec_len_b'] == 1583 and F[u'sec_len_c'] == 970
    assert F[u'sec_len_d'] == 5162 and F[u'sec_num'] == ['4..1', '5..5', '3', '7..6']
    assert F[u'sec_off_a'] == [56663, 65607] and F[u'sec_off_b'] == [40321, 41904]
