    def low_word(t, w):
        """全小写且前后不接字母(大写形与复合词都不算): 逐字符词界档。"""
        c, k = 0, t.find(w)
        while k >= 0:
            a = t[k - 1] if k > 0 else u''
            b = t[k + len(w)] if k + len(w) < len(t) else u''
            alpha = lambda x: bool(x) and (u'a' <= x <= u'z' or u'A' <= x <= u'Z')
            if not alpha(a) and not alpha(b) and t[k:k + len(w)] == w:
                c += 1
            k = t.find(w, k + 1)
        return c


