    POOL = sorted(POOL)
    CROSS = dict(((t, x), sum(1 for k in range(NSRC) if pnorm(x) in FAN[k])) for (t, x) in POOL)
    POOLC = [(t, CROSS[(t, x)], x) for (t, x) in POOL]
