    assert F[u'cd_verdict_same_minus_hol'] == 0 and F[u'ch_c64'] == [0, 0, 1, 0]
    assert F[u'ch_c64_fold'] == [0, 0, 2, 0] and F[u'ch_c64_two'] == [0, 0, 1, 0]
