    F[u'wrap_lit_zero'] = len([k for k in NEEDLEK if sum(F[u'delta_' + k]) and sum(F[u'lit_' + k]) == 0])
    F[u'wrap_delta_hit'] = len([k for k in NEEDLEK if sum(F[u'delta_' + k])])
    F[u'wrap_close'] = F[u'wrap_delta_hit'] - F[u'wrap_lit_zero']
