    Z(u"1 - F['fold_split_8200']", u'8200 面上“not optional”被行界劈开: 折平档 1 枚 ⇎ 逐行档 0 枚(读到逐行档非零即为失败态)')
    Z(u"F['obs_n'][2] - F['upd_n'][3]", u'8200 废止一枚 ⇎ 6935 更新一枚: 数量同、动作词不同')
    Z(u"1 - F['both_2460']", u'8200 与 6935 的动作对象都读到 2460(读不到即为失败态)')
    Z(u"F['win_named'] - NSRC", u'四份都定位到答句所在小节的标题行')
    Z(u"F['sn_strict_docs'][2]", u'8200 的答句整段被行界劈开: 逐行档一枚不中(本条折平档必需的最强证据)')
    Z(u"len([i for i in range(NSRC) if F['sn_strict_docs'][i]]) - 3",
      u'逐行档命中三份, 8200 一份全落空(四份都落空则阶梯证据反了)')
    Z(u"F['cite_forms_2460'][3] - F['cite_forms_2460'][2]", u'2460 的引用写法族在 8200 ⇎ 6935 里同数(两族都现读)')
    Z(u"1 - F['std_no_upper']", u'8200 是带 STD: 号的现行标准而全篇零大写义务词(读到一枚即为失败态)')
    Z(u"len(F['up_zero_docs']) - 2", u'零大写义务词的恰是 768 与 8200 两份')
    Z(u"F['opt_line_ck'][0]", u'768 面上 optional 一枚都不与 checksum 同行(它唯一的 optional 说的是源端口)')
    Z(u"F['opt_word'][0] - 1", u'768 全篇只写了一枚 optional')
    Z(u"sum(F['never_opt']) - 1", u'“never optional”全库恰一枚, 落在 1122 的 TCP 侧(与同文 UDP 那句 optional 对照)')
    Z(u"F['digit_chars'][0] - F['win_dig_in'][0] - F['win_dig_out'][0]", u'768 短面上的数字符按窗切分前后一致')
    Z(u"sum(F['win_close_up'])", u'大写义务词按窗切分的带内+带外=全篇(与四轨账同向再核一遍)')
    F['zid_n'] = len(ZID)
    ZF = [w for e, w in ZID if eval(e.strip().replace(u'\n', u''), dict(globals(), F=F, CLOSE=CLOSE, NSRC=NSRC, len=len, sum=sum, max=max, min=min, abs=abs, range=range, re=re))]
    F['zid_fail'] = ZF


    def _ev(e):
        return eval(e.strip().replace(u'\n', u''), dict(globals(), F=F, CLOSE=CLOSE, NSRC=NSRC, len=len, sum=sum, max=max, min=min, abs=abs, range=range, re=re))


    for e, w in ZID:
        if _ev(e):
            _sil(u'  失败: ' + w + u' <= ' + e.strip() + u' -> ' + repr(_ev(e)))
    F['scalar_clos_n'] = len(ZID)
    F['scalar_clos_sum'] = sum(1 for e, w in ZID if not _ev(e))
    F['list_clos_n'] = len([k for k in F if (u'_close' in k or u'_ledger' in k) and isinstance(F[k], list)])
    F['x_ident_n'] = len(ZID)

    # ---------- 折平偏移 ⇎ 原行号的双向尺 ----------
    def fmap(i):
        mp = []
        off = 0
        first = True
        for n, x in enumerate(L[i], 1):
            s = u' '.join(x.split())
            if not s:
                continue
            if not first:
                off += 1
            first = False
            mp.append((off, n))
            off += len(s)
        return mp


    FMP = [fmap(i) for i in range(NSRC)]
    for i in range(NSRC):
        assert u' '.join(u' '.join(x.split()) for x in L[i] if u' '.join(x.split())) == FOLD[i], i


    def line_of(i, a):
        r = 0
        for o, n in FMP[i]:
            if o <= a:
                r = n
            else:
                break
        return r


    def blk(i, start, end):
        """段落 = 折平面上从 start 起到 end(含) 的那一段; 起止都只按字面针定位, 行号由偏移现映"""
        a = FOLD[i].find(start)
        if a < 0:
            raise AssertionError(u'段起针落空 %s' % start)
        b = FOLD[i].find(end, a)
        if b < 0:
            raise AssertionError(u'段止针落空 %s' % end)
        e = b + len(end)
        return u' '.join(FOLD[i][a:e].split()), line_of(i, a), line_of(i, e - 1)


    def ln_of(i, nd):
        a = FOLD[i].find(nd)
        if a < 0:
            raise AssertionError(u'行针落空 %s' % nd)
        return line_of(i, a)


    P82, P82_LO, P82_HI = blk(2, u'Unlike IPv4, the default behavior', u'zero checksum and should log the error.')
    P6Q, P6Q_LO, P6Q_HI = blk(3, u'Unlike IPv4, when UDP packets are', u'checksum, and should log the error.')
    P6R, P6R_LO, P6R_HI = blk(3, u'Whenever originating a UDP packet for a port', u'zero checksum and SHOULD log the error.')
    F['blk_lo'] = [P82_LO, P6Q_LO, P6R_LO]
    F['blk_hi'] = [P82_HI, P6Q_HI, P6R_HI]
    F['blk_rows'] = [P82_HI - P82_LO + 1, P6Q_HI - P6Q_LO + 1, P6R_HI - P6R_LO + 1]
    F['blk_words'] = [len(P82.split()), len(P6Q.split()), len(P6R.split())]
    W82 = P82.lower().split()
    W6Q = P6Q.lower().split()
    W6R = P6R.lower().split()
    F['w82_only'] = sorted(set(w for w in W82 if w not in W6Q))
    F['w6q_only'] = sorted(set(w for w in W6Q if w not in W82))
    F['w82_only_n'] = len(F['w82_only'])
    F['w6q_only_n'] = len(F['w6q_only'])
    F['w_common'] = len(set(W82) & set(W6Q))
    F['w_row_close'] = F['w82_only_n'] + F['w_common'] - len(set(W82))
    F['lead_insert'] = cnt_cur(P82, u'the default behavior') - cnt_cur(P6Q, u'the default behavior')
    F['repl_bydefault'] = cnt_cur(P6R, u'MUST by default')
    F['p82_bydefault'] = cnt_cur(P82, u'by default')
    F['comma_82'] = cnt_cur(P82, u'checksum, and should')
    F['comma_q69'] = cnt_cur(P6Q, u'checksum, and should')
    F['comma_diff'] = F['comma_q69'] - F['comma_82']


    def suffix_words(a, b):
        n = 0
        while n < min(len(a), len(b)) and a[-1 - n] == b[-1 - n]:
            n += 1
        return n


    def head_words(a, b):
        n = 0
        while n < min(len(a), len(b)) and a[n] == b[n]:
            n += 1
        return n


    F['suf_82_q69'] = suffix_words(W82, W6Q)
    F['pre_82_q69'] = head_words(W82, W6Q)
    F['suf_82_6r'] = suffix_words(W82, W6R)
    F['pre_82_6r'] = head_words(W82, W6R)
    F['tone_up_repl'] = ub(P6R, u'MUST') + ub(P6R, u'MAY') + ub(P6R, u'SHOULD')
    F['tone_lo_repl'] = ub(P6R, u'must') + ub(P6R, u'may') + ub(P6R, u'should')
    F['tone_lo_82'] = ub(P82, u'must') + ub(P82, u'should')
