    def cnt_cur(hay, nd):
        """非重叠游标计数(采集侧是重叠口径, 两者差单独立键对账)"""
        c = 0
        i = 0
        n = len(nd)
        while True:
            j = hay.find(nd, i)
            if j < 0:
                return c
            c += 1
            i = j + n


    def cnt_ovl(hay, nd):
        c = 0
        i = 0
        while True:
            j = hay.find(nd, i)
            if j < 0:
                return c
            c += 1
            i = j + 1


