        first = True
        for n, x in enumerate(L[i], 1):
            if shell_line(x):
                continue
            s = u' '.join(x.split())
            if not s:
                continue
            if not first:
                off += 1
            first = False
            mp.append((off, n))
            off += len(s)
        return mp


