class ProofError(Exception):
    pass

def _resolve(tag, S, aset, bucket, kind):
    """锚点核验。声明了 DERIV 算式的锚点**必须**跑证明(即便它能作为子串偶然命中源文本,
    例如经纬度里恰好含有该数字); 未声明者才退回字面命中。"""
    for a in sorted(aset):
        expr = DERIV.get(tag, {}).get(a)
        if expr:
            ok, err = check_proof(tag, a, expr)
            if err:
                bucket.append(a + '(证明失败:' + err + ')')
            else:
                proofs.append(ok + ('  [亦偶然字面命中]' if norm(a) in S else ''))
        elif norm(a) not in S:
            bucket.append(a)

