    SP = [set(x for x in sents(WIDE[i]) if len(x) >= 40) for i in range(NSRC)]
    SPRES = dict((a, tuple(i for i in range(NSRC) if a in SP[i])) for s in SP for a in s)
    F['s_pool_n'] = len(SPRES)
