    def _ev(e):
        return eval(e.strip().replace(u'\n', u''), dict(globals(), F=F, CLOSE=CLOSE, T=T, WIDE=WIDE, LBL=LBL, NSRC=NSRC, len=len, sum=sum, max=max, min=min, abs=abs, range=range, re=re, str=str, int=int, sorted=sorted))


    ZF = [w for e, w in ZID if _ev(e)]
