    _s3 = sum(len(v) * (len(v) - 1) * (len(v) - 2) // 6 for v in SPRES.values())
    _s4 = sum(len(v) * (len(v) - 1) * (len(v) - 2) * (len(v) - 3) // 24 for v in SPRES.values())
    _s5 = len([v for v in SPRES.values() if len(v) == 5])
