    F[u'pp_shell_nonblank'] = [F[u'shell_lines'][i] - F[u'blank'][i] for i in range(NSRC)]
    F[u'pp_gap_close'] = sum(abs(F[u'pp_gap_rows'][i] - F[u'pp_shell_nonblank'][i]) for i in range(NSRC))
