    assert [F['cit_brk'][i] for i in RFCI] == [0, 0, 0] and [F['cit_rfc'][i] for i in PAPI] == [1, 4]

    # ---------- 节窗(编号解析成整数元组再比大小; 采集侧是一条正则的 group) ----------
    WIN = [u'AQM Algorithm Deployment SHOULD NOT Require Operational',
           u'its default target delay of 20 ms',
           u'defaulted to 15 milliseconds', u'50 ms baseline latency', u'minimum TARGET of 5 ms']


    def dotrun(x):
        """行内最长的连续点串长度: 目录行的引道符由它导出, 采集侧写 \\.{3,}"""
        best = 0
        cur = 0
        for c in x:
            if c == u'.':
                cur += 1
                if cur > best:
                    best = cur
            else:
                cur = 0
        return best


    def roman_shape(x):
        """论文面节题形状: 前导空格后是一串 I/V/X, 紧跟一点、至少一枚空白, 再一个大写字母。
        返回 (罗马数字串, 长度) 或 (u'', 0)——采集侧用 ^\\s*([IVX]+)\\.\\s+[A-Z] 一条正则拿到同一个串。"""
        k = 0
        while k < len(x) and x[k] == u' ':
            k += 1
        j = k
        while j < len(x) and x[j] in u'IVX':
            j += 1
        if j == k or j >= len(x) or x[j] != u'.':
            return u'', 0
        m = j + 1
        while m < len(x) and x[m] == u' ':
            m += 1
        if m >= len(x) or x[m] < u'A' or x[m] > u'Z':
            return u'', 0
        return x[k:j], j - k


    F['sec_no'] = []
    F['sec_title'] = []
    F['sec_lines'] = []
    F['sec_chars'] = []
    F['sec_tone'] = []
    F['sec_numval'] = []
    F['sec_par'] = []
    F['sec_role'] = []
    TOCL = []
    BODYL = []
    HITN = []
    for i in range(NSRC):
        hit = [x for x, y in enumerate(L[i]) if WIN[i] in y]
        assert hit, (i, WIN[i])
        HITN.append(len(hit))
        TOCL.append(hit[0] + 1 if len(hit) > 1 else None)
        k = hit[-1]
        BODYL.append(k + 1)
        if FAM[i] == u'rfc':
            # 本遍节题 = 有编号形状 ⇎ 行内没有 3 枚以上的连续点(目录引道符)
            heads = [(x, HS[i][x]) for x in range(len(L[i])) if HS[i][x][3] and dotrun(L[i][x]) < 3]
        else:
            heads = [(x, (0, 1, roman_shape(L[i][x])[0], 1, 0)) for x in range(len(L[i]))
                     if roman_shape(L[i][x])[1] > 0 and dotrun(L[i][x]) < 3]
        assert heads, i
        bg = [h for h in heads if h[0] <= k][-1]
        if FAM[i] == u'rfc':
            cur = tuple([int(z) for z in bg[1][2].split(u'.')])
            lvl = len(cur)
        else:
            cur, lvl = (0,), 1
        nxt = len(L[i])
        for x, h in heads:
            if x <= bg[0]:
                continue
            if FAM[i] == u'rfc':
                if h[1] == 0:
                    continue
                tup = tuple([int(z) for z in h[2].split(u'.')])
                if len(tup) <= lvl and tup >= cur:
                    nxt = x
                    break
            else:
                nxt = x
                break
        w = fold(NL.join(x for x in L[i][bg[0]:nxt] if not is_shell_pick(x, FAM[i])))
        F['sec_no'].append(bg[1][2])
        F['sec_title'].append(fold(L[i][bg[0]]))
        F['sec_lines'].append(nxt - bg[0])
        F['sec_chars'].append(len(w))
        F['sec_tone'].append([ub(w, nd) for nd in TONE])
        F['sec_numval'].append(sorted(set(num_pairs(w.lower(), UNITW))))
        F['sec_par'].append([cnt_re(w, nd) for nd in PAR])
        F['sec_role'].append([kk for kk in range(len(ROLEN)) if F['role_src'][kk] == LBL[i]
                              and ROLEN[kk] in w.lower()])
    F['sec_hit_n'] = HITN
    F['sec_toc_line'] = TOCL
    F['sec_body_line'] = BODYL
    F['sec_tone_tot'] = [sum(x) for x in F['sec_tone']]
    F['sec_span_pct'] = [round(100.0 * F['sec_chars'][i] / F['sh_chars'][i], 1) for i in range(NSRC)]
    # 采集侧靠 ARAB/ROMAN 两条正则的 group(1), 本遍靠 head_shape 的点段与 roman_shape 的字符扫: 逐份同串
    F['sec_no_pick'] = []
    for i in range(NSRC):
        rx = re.compile(u'^\\s*(\\d+(?:\\.\\d+)*)\\.?\\s+\\S') if FAM[i] == u'rfc' \
            else re.compile(u'^\\s*([IVX]+)\\.\\s+[A-Z]')
        hh = [(x, rx.match(L[i][x])) for x in range(len(L[i])) if rx.match(L[i][x]) and LEADER.search(L[i][x]) is None]
        F['sec_no_pick'].append([h for h in hh if h[0] <= F['sec_body_line'][i] - 1][-1][1].group(1))
    assert F['sec_no_pick'] == F['sec_no'], (F['sec_no'], F['sec_no_pick'])
    SUB43 = [x + 1 for x, y in enumerate(L[4]) if re.match(u'^4\\.3\\.\\s', y)]
    assert len(SUB43) == 1 and SUB43[0] > F['sec_body_line'][4]
    F['sec_sub_line'] = SUB43[0]
    F['sec_sub_title'] = fold(L[4][SUB43[0] - 1])
    assert F['sec_no'] == [u'4.3', u'I', u'8', u'IV', u'4'], F['sec_no']
    assert F['sec_lines'] == [69, 8, 32, 113, 91] and F['sec_chars'] == [2743, 3642, 1108, 7355, 4469]
    assert F['sec_tone_tot'] == [9, 0, 0, 0, 4]
    assert F['sec_hit_n'][0] == 2 and F['sec_toc_line'][0] == 136 and F['sec_body_line'][0] == 1071
    assert [x is None for x in F['sec_toc_line']] == [False, True, True, True, True]
    assert [F['sec_body_line'][i] > F['sec_lines'][i] for i in range(NSRC)] == [True] * NSRC

    # ---------- 答案句: 句界由逐字符扫导出(采集侧用 \.\\s(?=[A-Z(“]) 前瞻正则) ----------
    def sent_end(s, frm):
        """从 frm 起找第一个“句点+至少一枚空白+大写或左括号/左引号”的句点位;
        扫不到就退到 frm 之后的最后一枚句点, 连一枚也没有就退到串尾——标题行正是这种(它没有句点)。
        采集侧的 \\.\\\\s 只容一枚空白, 本遍容多枚; 折平面上多余的空格已被 fold 吞掉, 两把尺同点。"""
        n = len(s)
        start = u'ABCDEFGHIJKLMNOPQRSTUVWXYZ(“"'
        k = frm
        while k < n:
            if s[k] == u'.':
                j = k + 1
                while j < n and s[j].isspace():
                    j += 1
                if j > k + 1 and j < n and s[j] in start:
                    return k
            k += 1
        d = s.rfind(u'.', frm)
        return d if d >= frm else n - 1


    ANS = []
    SPAN = []
    BLOCKN = []
    ANSHELL = []
    ANSROW = []
    for i, pat in enumerate(WIN):
        hit = [x for x, y in enumerate(L[i]) if pat in y]
        ln = hit[-1]
        lo = ln
        while lo - 1 >= 0 and L[i][lo - 1].strip() != u'':
            lo -= 1
        hi = ln
        while hi + 1 < len(L[i]) and L[i][hi + 1].strip() != u'':
            hi += 1
        blk = L[i][lo:hi + 1]
        ANSHELL.append(len([x for x in blk if is_shell_pick(x, FAM[i]) and x.strip() != u'']))
        rows = [fold(x) for x in blk if x.strip() != u'' and not is_shell_pick(x, FAM[i])]
        txt, offs = u'', []
        for y in rows:
            offs.append(len(txt))
            txt += (u'' if txt == u'' else u' ') + y
        st = txt.lower().find(pat.lower())
        assert st >= 0, (LBL[i], pat)
        e = sent_end(txt, st + len(pat))
        assert e >= st, (LBL[i], txt[st:st + 40])
        ANS.append(txt[st:e + 1])
        SPAN.append(len([kk for kk in range(len(rows))
                         if offs[kk] <= e and offs[kk] + len(rows[kk]) >= st]))
        BLOCKN.append(len(rows))
        ANSROW.append(ln + 1)
    F['ans'] = ANS
    F['ans_words'] = [len(x.split()) for x in ANS]
    F['ans_span'] = SPAN
    F['ans_block_lines'] = BLOCKN
    F['ans_shell_rows'] = ANSHELL
    F['ans_anchor_line'] = ANSROW
    F['ans_one_line_n'] = len([x for x in SPAN if x == 1])
    F['ans_span_tot'] = sum(SPAN)
    F['ans_punct'] = [1 if x.endswith(u'.') else 0 for x in ANS]
    F['ans_punct_n'] = sum(F['ans_punct'])
    assert F['ans_span'] == [1, 1, 3, 1, 2] and F['ans_block_lines'] == [1, 7, 6, 5, 14]
    assert F['ans_shell_rows'] == [0] * NSRC and F['ans_words'] == [8, 24, 22, 4, 10]
    # 五根锚的读法: 三枚落在单行(RFC 标题行 ⇎ 两份论文的整段一行), 两枚跨行(72 列折行的 RFC 正文)
    assert F['ans_one_line_n'] == 3 and F['ans_span_tot'] == 8
