             u'term_minor', u'term_major', u'term_skew', u'term_own', u'rtt_tight', u'rtt_kern', u'rtt_loose',
             u'rtt_loose_false', u'unit', u'unit_word', u'unit_sub_over', u'numval_n', u'num', u'num_own',
