    ZEXP(u"B86V('kw2_pair_n') - B86V('kw_pair_n')", u'模板段配对数两遍同值')
    ZEXP(u"sum(B86V('kw2_same')) - sum(B86V('kw_same'))", u'模板段二百码位窗相同的对数两遍同判')
