    ZEXP(u"sum(B86V('dur_by_form')) - sum([sum(x) for x in B86V('dur')])", u'时长十式: 逐式合计 = 逐份总和')
    ZEXP(u"sum(B86V('dur_by_doc')) - sum(B86V('dur_by_form'))", u'时长十式: 两把聚合尺同值')
    ZEXP(u"B86V('bool2_green') - B86V('bool2_all')", u'发射遍布尔门全绿')
