    F['fam_ruler_diff'] = sum([1 for i in range(NSRC) for k in range(len(FAMS))
                               if not (F['fam_ub'][i][k] == F['fam_ub_re'][i][k] == F['fam_ub_cur'][i][k])])
    F['fam_wrap'] = [F['fam_sub'][i][k] - F['fam_ub'][i][k] for i in range(NSRC) for k in range(len(FAMS))]
