    def block_b(i, a_nd, b_nd):
        a = find_line_b(i, a_nd)
        b = find_line_b(i, b_nd, a + 1)
        assert a >= 0 and b > a, (a_nd, b_nd, a, b)
        return NL.join([x for x in L[i][a:b] if not shell_shape(x, i)])
    
    
