rows, fails, proofs, soft_all = [], [], [], []
tot_o = tot_b = 0
enc_all = ''
for p in sorted(glob.glob('corpus/babeltele/B*.md')):
    t = open(p, encoding='utf-8').read()
    tag = os.path.basename(p)[:3]
    orig = re.search(r'\[\[原始语料\|ORIGINAL\]\]\n(.*?)\n\n## ⟪BabelTele', t, re.S).group(1)
    enc = re.search(r'⟪BabelTele⟫\n(.*?)\n\n## ', t, re.S).group(1)
    gloss = t.split('## ')[-1]
    S = src_text(tag)
    bad, bad_o, soft = [], [], []
    enc_hard, enc_tiny = anchors(enc)
    orig_hard, _ = anchors(orig)
    _resolve(tag, S, enc_hard, bad, 'enc')
    _resolve(tag, S, orig_hard, bad_o, 'orig')
    src_tiny_hard, src_tiny = anchors(src_raw(tag))
    for a in enc_tiny:
        expr = DERIV.get(tag, {}).get(a)
        if expr:
            ok, err = check_proof(tag, a, expr)
            if ok:
                proofs.append(ok)
            else:
                soft.append(a + '(' + err + ')')
        elif a not in src_tiny:
            soft.append(a)
    for c in check_paren_uncertainties(tag, enc, orig):
        (bad if c.startswith('✗') else proofs).append(c)
    claims = check_script_claims(tag, enc, orig)
    for c in claims:
        (bad if c.startswith('✗') else proofs).append(c)
    miss_cp = check_codepoints(tag, enc) + check_subtags(tag, enc) + check_atoms(tag, enc, orig)
    n = len(enc.replace('\n', ''))
    uniq = len(set(enc.replace('\n', '')))
    sc = Counter(block_of(ord(c)) for c in enc.replace('\n', '') if block_of(ord(c)))
    words = len(re.findall(r'\w+|\d[\d.]*', enc)) or 1
    rawlen = sum(os.path.getsize(f) for f in SRC.get(tag, []) if os.path.exists(f)) or 1
    rows.append((tag, len(orig), n, n / len(orig) * 100, n / rawlen * 100, uniq, len(sc), n / words,
                 len(bad), len(bad_o), len(miss_cp), len(soft)))
    tot_o += len(orig); tot_b += n; enc_all += enc
    soft_all.append((tag, sorted(soft)))
    if bad or bad_o or miss_cp:
        fails.append((tag, bad, bad_o, miss_cp, sorted(soft)))

# 结构自检: 每个条目的复算器在本文件里只能定义一次、被调用一次(重复定义会让先前的定义静默失效)
SELF = io.open(__file__, encoding='utf-8', errors='replace').read()
DUP = {}
for nm in sorted(set(re.findall(r'def (_b[0-9]+_scan)\(', SELF))):
    nd = len(re.findall(r'def ' + nm + r'\(', SELF))
    nc = len(re.findall(r'= ' + nm + r'\(\)', SELF))
    if nd != 1 or nc != 1:
        DUP[nm] = (nd, nc)
if DUP:
    fails.append(('SELF', sorted(DUP.items()), {}, {}, []))

print('| id | 原文 | 编码 | 保留率↓(vs 摘要段) | vs raw源↓ | 唯一码点 | 区块 | 字符/语义单元↓ | T1/T2 编码失配 | 原文失配 | T3 码位失配 | 小整数待核 |')
print('|---|---|---|---|---|---|---|---|---|---|---|---|')
for r in rows:
    print('| %s | %d | %d | %.1f%% | %.3f%% | %d | %d | %.2f | %d | %d | %d | %d |' % r)
uniq_all = len(set(enc_all.replace('\n', '')))
print('| ALL | %d | %d | **%.1f%%** | — | %d | — | — | %d | %d | %d | %d |' % (
    tot_o, tot_b, tot_b / tot_o * 100, uniq_all,
    sum(r[8] for r in rows), sum(r[9] for r in rows), sum(r[10] for r in rows), sum(r[11] for r in rows)))

print('\n已机检的推导(%d 条):' % len(proofs))
for x in proofs:
    print('  ✓', x)
print('\n保真门槛(T1 字面 + T2 推导 + T3 码位):', 'PASS' if not fails else 'FAIL')
for tag, b, bo, mc, sf in fails:
    print('  %s: 编码侧=%s 原文侧=%s 码位=%s' % (tag, b, bo, mc))
soft_tot = sum(r[11] for r in rows)
if soft_tot:
    print('\n提示(不计入 FAIL, 1-2 位结构计数未逐位核验): 共 %d 个' % soft_tot)
    for tag, sf in soft_all:
        if sf:
            print('  ', tag, sf)
